import base64,json,pathlib,shlex,subprocess,time
source="import json,pathlib,subprocess,re\nroot=pathlib.Path('/home/ubuntu/twin-v2')\nout={'liveSource':{},'v2Files':[],'v1Root':[],'v1Relevant':[]}\nfor f in ['src/memory.ts','src/config.ts','src/gate.ts']:\n p=root/f\n if p.exists():\n  lines=p.read_text().splitlines()\n  if f.endswith('memory.ts'):out['liveSource'][f]='\\n'.join(lines[25:80])\n  elif f.endswith('config.ts'):out['liveSource'][f]='\\n'.join(l for l in lines if any(k in l for k in ['dataDir','logDir','memory','credits']))\nfor folder in ['data','logs']:\n for p in (root/folder).rglob('*'):\n  if p.is_file() and p.suffix in ['.jsonl','.log','.out']:\n   total=matches=0\n   with p.open(errors='replace') as f:\n    for line in f:\n     total+=1\n     if '6814483810' in line or '@rcy07' in line.lower():matches+=1\n   if matches:out['v2Files'].append({'path':str(p.relative_to(root)),'bytes':p.stat().st_size,'lines':total,'matchedLines':matches})\nv1=pathlib.Path('/home/ubuntu/allieai2-bot')\nout['v1Root']=[p.name for p in v1.iterdir() if not p.name.startswith('.')]\nfor p in v1.rglob('*'):\n if any(x in ['node_modules','.git','logs','data'] for x in p.relative_to(v1).parts):continue\n if p.is_file() and p.suffix in ['.ts','.js','.mjs','.py'] and p.stat().st_size<1000000:\n  lines=p.read_text(errors='replace').splitlines()\n  found=[{'line':i+1,'text':line[:200]} for i,line in enumerate(lines) if re.search(r'fan_profiles|chat_history|stated_name|new Redis|createClient.*redis|cache.*history|history.*cache|delete.*history|reset.*memory',line,re.I)]\n  if found:out['v1Relevant'].append({'file':str(p.relative_to(v1)),'found':found[:16]})\nprint('RESET_SOURCE '+json.dumps(out))\n"
command='python3 -c '+shlex.quote('import base64;exec(compile(base64.b64decode('+repr(base64.b64encode(source.encode()).decode())+'),"rcy07-preflight","exec"))')
p=pathlib.Path('/tmp/rcy07-ssm-params.json');p.write_text(json.dumps({'commands':[command],'executionTimeout':['120']}))
cid=subprocess.check_output(['aws','ssm','send-command','--instance-ids','i-0584d283506f3f6be','--document-name','AWS-RunShellScript','--parameters','file://'+str(p),'--comment','Read-only RCY07 reset preflight','--query','Command.CommandId','--output','text'],text=True).strip()
print('COMMAND '+cid,flush=True)
for _ in range(50):
 time.sleep(2)
 try:r=json.loads(subprocess.check_output(['aws','ssm','get-command-invocation','--command-id',cid,'--instance-id','i-0584d283506f3f6be','--output','json'],text=True,stderr=subprocess.DEVNULL))
 except subprocess.CalledProcessError:continue
 if r['Status'] in ['Success','Failed','Cancelled','TimedOut']:break
else:raise RuntimeError('SSM still running; inspect command '+cid)
print(r.get('StandardOutputContent',''),flush=True)
if r['Status']!='Success':raise RuntimeError(r.get('StandardErrorContent','')[-1500:])
